@php`n$adminMenuItems = \App\Models\AdminMenuItem::getOrdered();`nfunction adminMenuActiveRoutes($item) {`n    if ($item->is_dropdown && !empty($item->children)) {`n        $patterns = array_map(fn($c) => str_replace("." , "*", $c["route_name"]), $item->children);`n        return implode("," , $patterns);`n    }`n    return $item->route_name . "*";`n}`nfunction adminMenuIsActive($item) {`n    if ($item->is_dropdown && !empty($item->children)) {`n        $routeNames = array_column($item->children, "route_name");`n        return request()->routeIs(...$routeNames);`n    }`n    return request()->routeIs($item->route_name);`n}`nfunction adminMenuChildIsActive($routeName) {`n    return request()->routeIs($routeName);`n}`n@endphp`n`n@foreach($adminMenuItems as $item)`n    @if($item->is_dropdown && !empty($item->children))`n        @php $isActive = adminMenuIsActive($item); @endphp`n        <div class="nav-dropdown {{ $isActive ? "active" : "" }}">`n            <button type="button" class="w-full flex items-center justify-between gap-3 px-3 py-2.5 rounded-lg text-green-100 hover:bg-green-700 hover:text-white transition-colors nav-dropdown-trigger">`n                <div class="flex items-center gap-3">`n                    {!! $item->icon_svg !!}`n                    <span>{{ $item->label }}</span>`n                </div>`n                <svg class="w-4 h-4 transition-transform nav-dropdown-icon" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M19 9l-7 7-7-7"/></svg>`n            </button>`n            <div class="nav-dropdown-content space-y-1 pl-6 mt-1">`n                @foreach($item->children as $child)`n                    @php $childActive = adminMenuChildIsActive($child["route_name"]); @endphp`n                    <a href="{{ route($child["route_name"]) }}" class="flex items-center gap-3 px-3 py-2 rounded-lg text-sm text-green-100 hover:bg-green-700 hover:text-white transition-all {{ $childActive ? "sidebar-link-active" : "" }}">`n                        <svg class="w-4 h-4 flex-shrink-0" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M9 12h6m-6 4h6m2 5H7a2 2 0 01-2-2V5a2 2 0 012-2h5.586a1 1 0 01.707.293l5.414 5.414a1 1 0 01.293.707V19a2 2 0 01-2 2z"/></svg>`n                        <span>{{ $child["label"] }}</span>`n                        @if($child["route_name"] === "admin.contatos.index")`n                            @php $newContacts = \App\Models\Contact::where("status","new")->count(); @endphp`n                            @if($newContacts > 0)<span class="ml-auto bg-red-500 text-white text-[10px] rounded-full px-1.5 py-0.5">{{ $newContacts }}</span>@endif`n                        @endif`n                    </a>`n                @endforeach`n            </div>`n        </div>`n    @else`n        @php $isActive = adminMenuIsActive($item); @endphp`n        <a href="{{ $item->route_name === "#" ? "#" : route($item->route_name) }}" class="flex items-center gap-3 px-3 py-2.5 rounded-lg text-green-100 hover:bg-green-700 hover:text-white transition-colors {{ $isActive ? "bg-green-700 text-white" : "" }}">`n            {!! $item->icon_svg !!}`n            {{ $item->label }}`n        </a>`n    @endif`n@endforeach`n`n<div class="my-2 border-t border-green-700/50"></div>`n`n<div class="space-y-1">`n    <p class="px-3 text-[10px] font-bold text-green-500 uppercase tracking-wider">Personalização</p>`n    <a href="{{ route("admin.menu.index") }}" class="flex items-center gap-3 px-3 py-2.5 rounded-lg text-green-300 hover:bg-green-700 hover:text-white transition-colors text-sm {{ request()->routeIs("admin.menu*") ? "bg-green-700 text-white" : "" }}">`n        <svg class="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path stroke-linecap="round" stroke-linejoin="round" stroke-width="2" d="M4 6h16M4 12h16M4 18h16"/></svg>`n        <span>Editor de Menu Admin</span